public class FenwickTour {
    static long[] tree;                      // 1-based: tree[0] is unused

    static void add(int i, long delta) {     // i is 1-based
        for (; i < tree.length; i += i & -i) tree[i] += delta;
    }

    static long prefix(int i) {              // sum of positions 1..i
        long sum = 0;
        for (; i > 0; i -= i & -i) sum += tree[i];
        return sum;
    }

    static long rangeSum(int l, int r) { return prefix(r) - prefix(l - 1); }

    public static void main(String[] args) {
        int[] steps = {3000, 4500, 2000, 8000, 6500, 1000, 7000, 5000};   // days 1..8
        tree = new long[steps.length + 1];
        for (int day = 1; day <= steps.length; day++) add(day, steps[day - 1]);
        System.out.println("total steps:       " + prefix(8));
        System.out.println("days 3..6:         " + rangeSum(3, 6));
        add(4, 1500);                        // a late sync adds 1500 steps to day 4
        System.out.println("days 3..6 after a +1500 sync on day 4: " + rangeSum(3, 6));
        System.out.println("first half / second half: " + prefix(4) + " / " + rangeSum(5, 8));
    }
}

import java.util.Arrays;

public class FenwickPrefixSums {
    public static void main(String[] args) {
        int[] a = {0, 5, 2, 9, 1, 6, 3, 8, 4};      // a[1..8]; a[0] unused
        int n = a.length - 1;

        long[] plain = new long[n + 1];             // plain prefix sums
        for (int i = 1; i <= n; i++) plain[i] = plain[i - 1] + a[i];

        long[] tree = new long[n + 1];
        for (int i = 1; i <= n; i++) tree[i] = a[i];
        for (int i = 1; i <= n; i++) {              // O(n) build: push each total to its parent
            int parent = i + (i & -i);
            if (parent <= n) tree[parent] += tree[i];
        }
        for (int i = 1; i <= n; i++) {
            int low = i & -i;
            System.out.printf("tree[%d] = %2d covers positions %d..%d%n", i, tree[i], i - low + 1, i);
        }

        System.out.print("prefix(7): visit");
        long sum = 0;
        for (int i = 7; i > 0; i -= i & -i) {
            System.out.print(" " + i);
            sum += tree[i];
        }
        System.out.println(" -> " + sum);

        long[] fromTree = new long[n + 1];
        for (int k = 1; k <= n; k++) {
            for (int i = k; i > 0; i -= i & -i) fromTree[k] += tree[i];
        }
        System.out.println("prefix sums from the tree: " + Arrays.toString(Arrays.copyOfRange(fromTree, 1, n + 1)));
        System.out.println("plain prefix sums:         " + Arrays.toString(Arrays.copyOfRange(plain, 1, n + 1)));
    }
}

import java.util.ArrayList;
import java.util.List;

public class FenwickRangeSum {
    static int[] a = {0, 4, 7, 1, 8, 2, 6, 9, 3, 5, 2, 7};     // a[1..11]
    static int n = a.length - 1;
    static long[] tree = new long[n + 1];

    static void add(int i, long delta) { for (; i <= n; i += i & -i) tree[i] += delta; }

    static long prefix(int i, List<Integer> visits) {
        long sum = 0;
        for (; i > 0; i -= i & -i) {
            sum += tree[i];
            if (visits != null) visits.add(i);
        }
        return sum;
    }

    static long rangeSum(int l, int r) { return prefix(r, null) - prefix(l - 1, null); }

    public static void main(String[] args) {
        for (int i = 1; i <= n; i++) add(i, a[i]);
        int[][] queries = {{3, 7}, {1, 4}, {6, 11}, {5, 5}};
        for (int[] q : queries) {
            List<Integer> right = new ArrayList<>(), left = new ArrayList<>();
            long value = prefix(q[1], right) - prefix(q[0] - 1, left);
            System.out.println("sum(" + q[0] + ", " + q[1] + ") = prefix(" + q[1] + ") " + right
                    + " - prefix(" + (q[0] - 1) + ") " + left + " = " + value);
        }
        int ok = 0, total = 0;
        for (int l = 1; l <= n; l++) {
            for (int r = l; r <= n; r++) {
                long brute = 0;
                for (int i = l; i <= r; i++) brute += a[i];
                total++;
                if (brute == rangeSum(l, r)) ok++;
            }
        }
        System.out.println(ok + " of " + total + " ranges match a brute-force sum");
    }
}

