import java.util.ArrayList;
import java.util.List;

public class FenwickPointUpdates {
    static long[] tree;

    static List<Integer> add(int i, long delta) {
        List<Integer> touched = new ArrayList<>();
        for (; i < tree.length; i += i & -i) {
            tree[i] += delta;
            touched.add(i);
        }
        return touched;
    }

    static long prefix(int i) {
        long sum = 0;
        for (; i > 0; i -= i & -i) sum += tree[i];
        return sum;
    }

    public static void main(String[] args) {
        tree = new long[17];
        for (int pos : new int[]{3, 5, 12, 16}) {
            System.out.println("update position " + pos + " touches cells " + add(pos, 1));
        }

        int[] a = {5, 2, 8, 1, 7, 3, 6, 4};          // values are ranks 1..8
        tree = new long[a.length + 1];
        long inversions = 0;
        int seen = 0;
        StringBuilder perStep = new StringBuilder();
        for (int v : a) {
            long greaterBefore = seen - prefix(v);   // query BEFORE adding v
            inversions += greaterBefore;
            perStep.append(greaterBefore).append(' ');
            add(v, 1);
            seen++;
        }
        long brute = 0;
        for (int i = 0; i < a.length; i++)
            for (int j = i + 1; j < a.length; j++)
                if (a[i] > a[j]) brute++;
        System.out.println("greater values seen before each element: " + perStep.toString().trim());
        System.out.println("inversions: " + inversions + " with the tree, " + brute + " with the O(n^2) double loop");
    }
}

import java.util.ArrayList;
import java.util.List;

public class LowerBit {
    static int lowbit(int i) { return i & -i; }

    public static void main(String[] args) {
        System.out.println(" i  binary  lowbit  cell covers");
        for (int i = 1; i <= 16; i++) {
            String bin = String.format("%5s", Integer.toBinaryString(i)).replace(' ', '0');
            System.out.printf("%2d  %s  %6d  %d..%d%n", i, bin, lowbit(i), i - lowbit(i) + 1, i);
        }
        List<Integer> query = new ArrayList<>();
        for (int i = 13; i > 0; i -= lowbit(i)) query.add(i);
        System.out.println("query chain from 13 (remove the low bit): " + query + " -> 0");
        List<Integer> update = new ArrayList<>();
        for (int i = 5; i <= 16; i += lowbit(i)) update.add(i);
        System.out.println("update chain from 5 (add the low bit):    " + update);
        System.out.println("12 & -12 = " + (12 & -12) + " (isolates), 12 & 11 = " + (12 & 11) + " (clears)");
    }
}

